WITH gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM sessions), sessions_sessions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, customer_id, started_at, country, session_start_flag FROM sessions_sessions ORDER BY country DESC NULLS LAST;
